// AI Agent + Structured Output Parser -> ผลลัพธ์อยู่ที่ $json.output
const src = $json.output || $json;
const ev  = $('Parse LINE Event').first().json;

const fallback = 'ขออภัยค่ะ ระบบขัดข้องชั่วคราว น้องอิ่มใจแจ้งทีมงานให้แล้ว เดี๋ยวทีมงานติดต่อกลับนะคะ';
let reply = (src.reply_text || '').toString().trim();
// บั๊กที่เจอบ่อย: โมเดลบางครั้งพิมพ์ตัวอักษร \\n เป็นข้อความล้วน ๆ แทนการขึ้นบรรทัดใหม่จริง -> แก้ให้เป็นบรรทัดใหม่จริงเสมอ
reply = reply.replace(/\\r\\n/g, '\n').replace(/\\n/g, '\n');

// ── ตรวจจากขั้นตอนจริงที่ agent เรียก tool (intermediateSteps) ไม่พึ่งพาแค่คำพูดของ AI ──
const steps = $json.intermediateSteps || [];
let orderPlaced = false, orderInfo = null, ticketCreated = false;
for (const step of steps) {
  const toolName = ((step.action && (step.action.tool || step.action.toolName)) || step.tool || '').toString().toLowerCase();
  let obs = step.observation;
  if (typeof obs === 'object') { try { obs = JSON.stringify(obs); } catch (e) { obs = String(obs); } }
  obs = (obs || '').toString();
  if (/create.?order/.test(toolName) || (/order/.test(toolName) && /ORD-\d{8}-\d{3}/.test(obs))) {
    const m = obs.match(/ORD-\d{8}-\d{3}/);
    if (m) {
      orderPlaced = true;
      let total = null;
      const tm = obs.match(/total_amount["':\s]+([0-9]+(\.[0-9]+)?)/i);
      if (tm) total = tm[1];
      orderInfo = { order_id: m[0], raw_observation: obs, total_amount: total };
    }
  }
  if (/create.?ticket/.test(toolName) || (/ticket/.test(toolName) && /TK-\d{8}-\d{3}/.test(obs))) {
    ticketCreated = true;
  }
}

return [{
  json: {
    reply_text : reply || fallback,
    intent     : src.intent    || 'other',
    sentiment  : src.sentiment || 'Neutral',
    // ไม่มีข้อความตอบ = ระบบมีปัญหา -> บังคับส่งต่อแอดมิน (fail-safe)
    need_admin : reply ? !!src.need_admin : true,
    reason     : src.reason || (reply ? '-' : 'agent ไม่คืนข้อความตอบกลับ'),
    order_id_llm: src.order_id || '-',
    order_placed: orderPlaced,
    order_id   : orderPlaced ? orderInfo.order_id : '-',
    order_total_hint: orderPlaced ? orderInfo.total_amount : null,
    ticket_created: ticketCreated,
    userId     : ev.userId,
    replyToken : ev.replyToken,
    userMessage: ev.userMessage,
    timestamp  : ev.timestamp
  }
}];

// ── สร้าง payload แจ้งทีมงานเรื่องออเดอร์ใหม่ + ลิงก์ยืนยันการชำระเงินแบบปลอดภัย ──────────
// ลิงก์ไม่ได้ชี้ตรงไปที่ resume URL (กัน Discord prefetch กดยืนยันเอง)
// ต้องเปิดหน้ายืนยันแล้วกดปุ่มจริงก่อน ถึงจะ POST เข้า resume URL
const crypto = require('crypto');
const cfg = $('⚙️ Config').first().json;
const order = $input.first().json || {};
const order_id = order.order_id || $('Format Agent Output').first().json.order_id;

const secret = cfg.APPROVAL_SECRET || 'CHANGE_ME_ANY_RANDOM_STRING';
const token = crypto.createHash('sha256').update(String(order_id) + '|' + secret).digest('hex').slice(0, 24);
const resumeUrl = $execution.resumeUrl;
const base = (cfg.PUBLIC_BASE_URL || '').replace(/\/$/, '');
const confirmLink = base + '/webhook/imjai-payment-confirm-page'
  + '?order_id=' + encodeURIComponent(order_id)
  + '&token=' + token
  + '&resume=' + encodeURIComponent(resumeUrl);

const stamp = new Date(Date.now() + 7 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19);

const payload = {
  username: 'อิ่มใจ ออเดอร์ใหม่',
  content: '🛎️ **มีออเดอร์ใหม่ รอตรวจสลิป/ยืนยันการชำระเงิน**',
  embeds: [{
    title: '🧾 ' + order_id,
    color: 3447003,
    description:
      '**รายการ**\n' + (order.items || '-') + '\n\n' +
      '**กดเพื่อยืนยันหลังเช็คสลิป/เงินเข้าแล้วเท่านั้น (เปิดหน้ายืนยันแล้วกดปุ่มอีกครั้ง)**\n' +
      '✅ [ยืนยันว่าชำระเงินแล้ว](' + confirmLink + ')',
    fields: [
      { name: 'ลูกค้า', value: (order.customer_name || '-') + ' (' + (order.customer_phone || '-') + ')', inline: true },
      { name: 'ช่องทางรับของ', value: order.order_type || '-', inline: true },
      { name: 'ยอดชำระ', value: (order.total_amount || '-') + ' บาท', inline: true },
      { name: 'ที่อยู่จัดส่ง', value: order.delivery_address || '-', inline: false },
      { name: 'LINE user id', value: '`' + (order.line_user_id || '-') + '`', inline: false },
      { name: 'เวลาสั่ง', value: order.created_at || stamp, inline: false },
    ],
    footer: { text: 'ระบบจะยังไม่ขึ้นว่าชำระเงินแล้วจนกว่าทีมงานจะกดยืนยัน · ลิงก์หมดอายุใน 48 ชม.' },
  }],
};

return [{ json: { ...order, discord_webhook_url: cfg.DISCORD_WEBHOOK_URL, discord_payload: payload, confirm_link: confirmLink, notified_at: stamp } }];

// ── อ่านผลการยืนยันจากทีมงาน (ถ้าไม่มี = ถือว่ายังไม่ยืนยัน / หมดเวลา) ──────────────────
const prev = $('Build Order Notify Payload').first().json;
const inc = $input.first().json || {};
const body = inc.body || {};
const query = inc.query || {};

const raw = (body.decision || query.decision || '').toString().toLowerCase();
const confirmed = raw === 'confirm' || raw === 'paid' || raw === 'yes';
const timedOut = raw === '';
const confirmedBy = body.approver || query.approver || (timedOut ? 'ระบบ (หมดเวลา)' : 'ทีมงาน');
const decided_at = new Date(Date.now() + 7 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19);

return [{
  json: {
    ...prev,
    payment_confirmed: confirmed,
    timed_out: timedOut,
    confirmed_by: confirmedBy,
    decided_at,
  },
}];

// ── สร้างหน้ายืนยันการชำระเงิน (มือถือกดง่าย) ──────────────────────────────
// crawler ที่ prefetch ลิงก์จะได้แค่ HTML นี้ ไม่มีทางสั่งยืนยันได้
// เพราะการยืนยันจริงต้องกดปุ่ม -> ยิง POST เข้า resume URL เท่านั้น
const crypto = require('crypto');
// ⚠️ node นี้ถูกเรียกจาก webhook คนละตัว (Payment Confirm Page GET) จึงเป็นคนละ execution
// จาก LINE Webhook อ้างอิง node ⚙️ Config ข้าม execution ไม่ได้ ต้องตั้งค่าซ้ำตรงนี้ให้ตรงกับ
// APPROVAL_SECRET ใน ⚙️ Config เป๊ะ ๆ (แก้ที่นี่ด้วยทุกครั้งที่เปลี่ยนค่าใน Config)
let SECRET = 'CHANGE_ME_ANY_RANDOM_STRING';
try { if ($env && $env.IMJAI_APPROVAL_SECRET) SECRET = $env.IMJAI_APPROVAL_SECRET; } catch (e) {}

const q = $('Payment Confirm Page (GET)').first().json.query || {};
const order_id = (q.order_id || '').toString();
const token = (q.token || '').toString();
const resume = (q.resume || '').toString();

const expected = crypto.createHash('sha256').update(order_id + '|' + SECRET).digest('hex').slice(0, 24);
const valid = order_id && resume && token === expected;

const order = $input.first().json || {};
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const shell = (inner, bg) => `<!doctype html><html lang="th"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow"><title>ยืนยันการชำระเงิน — อิ่มใจ</title>
<style>
*{box-sizing:border-box}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Noto Sans Thai",sans-serif;
background:${bg};min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px;color:#1f2933}
.card{background:#fff;border-radius:20px;box-shadow:0 18px 50px rgba(0,0,0,.18);max-width:460px;width:100%;padding:28px}
h1{font-size:20px;margin:0 0 6px}.sub{color:#61707d;font-size:14px;margin:0 0 20px}
.row{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #eef1f4;font-size:14px}
.row b{color:#61707d;font-weight:500}
button{width:100%;border:0;border-radius:14px;padding:18px;font-size:17px;font-weight:700;color:#fff;cursor:pointer;margin-top:18px}
.ok{background:#16a34a}
input{width:100%;padding:12px;border:1px solid #d5dde3;border-radius:12px;margin-top:14px;font-size:15px}
.note{font-size:12px;color:#8a97a3;margin-top:14px;line-height:1.6}
.done{text-align:center}.done .em{font-size:52px}
</style></head><body><div class="card">${inner}</div></body></html>`;

if (!valid) {
  const html = shell(`<div class="done"><div class="em">🚫</div>
    <h1>ลิงก์ไม่ถูกต้องหรือหมดอายุ</h1>
    <p class="sub">ไม่สามารถยืนยันตัวตนของลิงก์นี้ได้ กรุณาเปิดลิงก์จากข้อความแจ้งเตือนใน Discord อีกครั้ง
    หรือติดต่อผู้ดูแลระบบ</p></div>`, '#f1f5f9');
  return [{ json: { html, valid: false } }];
}

const html = shell(`
  <h1>✅ ยืนยันการชำระเงิน</h1>
  <p class="sub">เช็คสลิป/เงินเข้าบัญชีแล้วเท่านั้นถึงกดปุ่มนี้ ระบบจะขึ้นว่า 'ชำระแล้ว' ให้ลูกค้าทันทีหลังกด</p>
  <div class="row"><b>เลขที่ออเดอร์</b><span>${esc(order_id)}</span></div>
  <div class="row"><b>ลูกค้า</b><span>${esc(order.customer_name)} (${esc(order.customer_phone)})</span></div>
  <div class="row"><b>รายการ</b><span>${esc(order.items)}</span></div>
  <div class="row"><b>ยอดชำระ</b><span>${esc(order.total_amount)} บาท</span></div>
  <div class="row"><b>ช่องทางรับของ</b><span>${esc(order.order_type)}</span></div>
  <input id="approver" placeholder="ชื่อผู้ยืนยัน (เช่น พนักงานเก็บเงิน)" />
  <button class="ok" id="go">ยืนยันว่าชำระเงินแล้ว</button>
  <p class="note">🔒 การเปิดหน้านี้ (รวมถึงการ preview ลิงก์อัตโนมัติของ Discord) จะไม่ทำให้เกิดการยืนยันเอง
  ต้องมีคนกดปุ่มนี้เท่านั้น ข้อมูลด้านบนดึงจากชีตล่าสุด ณ ตอนเปิดหน้านี้</p>
  <script>
  document.getElementById('go').addEventListener('click', async function () {
    var btn = this; btn.disabled = true; btn.textContent = 'กำลังส่ง...';
    try {
      var res = await fetch(${JSON.stringify(resume)}, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ decision: 'confirm', order_id: ${JSON.stringify(order_id)},
          approver: document.getElementById('approver').value || 'ทีมงาน' })
      });
      btn.textContent = res.ok ? '✅ ยืนยันเรียบร้อย ปิดหน้านี้ได้เลย' : 'เกิดข้อผิดพลาด ลองใหม่อีกครั้ง';
      if (!res.ok) btn.disabled = false;
    } catch (e) { btn.textContent = 'เกิดข้อผิดพลาด ลองใหม่อีกครั้ง'; btn.disabled = false; }
  });
  </script>
`, '#eef2ff');

return [{ json: { html, valid: true } }];

// ── ระบบมีปัญหา → แจ้งแอดมินทาง Discord ทันที ─────────────────────────────
// หมายเหตุ: Error Workflow รันเป็นคนละ execution จากตัวที่พัง จึงอ้างอิง node ⚙️ Config เดิมไม่ได้
// ต้องใส่ Discord Webhook URL ซ้ำอีกทีตรงนี้ (ใช้ตัวเดียวกับใน ⚙️ Config)
const WEBHOOK = 'PASTE_YOUR_DISCORD_WEBHOOK_URL_HERE';

const j = $input.first().json || {};
const err = j.execution || {};
const wf = j.workflow || {};
const stamp = new Date(Date.now() + 7 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19);

const payload = {
  username: 'อิ่มใจ System',
  content: '@here ⚠️ **ระบบ AI ลูกค้าสัมพันธ์มีปัญหา — รบกวนแอดมินเข้าดูแลลูกค้าแทนชั่วคราว**',
  embeds: [{
    title: '⚠️ Workflow error: ' + (wf.name || 'ImJai LINE AI Agent v2'),
    color: 10038562,
    fields: [
      { name: 'Node ที่พัง', value: '`' + ((err.lastNodeExecuted) || '-') + '`', inline: false },
      { name: 'ข้อความ error', value: '```' + String((err.error && err.error.message) || '-').slice(0, 900) + '```', inline: false },
      { name: 'เวลา', value: stamp, inline: true },
      { name: 'Execution', value: String(err.id || '-'), inline: true },
    ],
    footer: { text: 'ลูกค้าอาจไม่ได้รับคำตอบจากบอท กรุณาเช็ค LINE OA Manager' },
  }],
};

return [{ json: { discord_webhook_url: WEBHOOK, discord_payload: payload } }];
